const maps: Record<Exclude<InterfaceLanguage, 'en'>, PhraseMap> = {
  uk: { ...uk, ...supplementalUk },
  ru: { ...ru, ...supplementalRu },
};

const dynamic = (language: Exclude<InterfaceLanguage, 'en'>, value: string) => {
  const greeting = value.match(/^Good (morning|afternoon|evening), (.+)\.$/);
  if (greeting) {
    const prefix = language === 'uk'
      ? ({ morning: 'Доброго ранку', afternoon: 'Добрий день', evening: 'Добрий вечір' } as const)[greeting[1] as 'morning']
      : ({ morning: 'Доброе утро', afternoon: 'Добрый день', evening: 'Добрый вечер' } as const)[greeting[1] as 'morning'];
    return `${prefix}, ${greeting[2]}.`;
  }
  const available = value.match(/^(\d+) (White|Yellow|Blue) Sparks available$/);
  if (available) return language === 'uk' ? `Доступно: ${available[1]} ${available[2]} Sparks` : `Доступно: ${available[1]} ${available[2]} Sparks`;
  const remaining = value.match(/^(\d+) remaining$/);
  if (remaining) return language === 'uk' ? `Залишилося: ${remaining[1]}` : `Осталось: ${remaining[1]}`;
  const genericAvailable = value.match(/^(\d+) available$/);
  if (genericAvailable) return language === 'uk' ? `Доступно: ${genericAvailable[1]}` : `Доступно: ${genericAvailable[1]}`;
  const nominationsAvailable = value.match(/^(\d+) nominations? available$/);
  if (nominationsAvailable) return language === 'uk' ? `Доступно номінацій: ${nominationsAvailable[1]}` : `Доступно номинаций: ${nominationsAvailable[1]}`;
  const allocation = value.match(/^(Q\d \d{4}) allocation$/);
  if (allocation) return language === 'uk' ? `Квота ${allocation[1]}` : `Квота ${allocation[1]}`;
  const activeCategories = value.match(/^(\d+) active categories$/);
  if (activeCategories) return language === 'uk' ? `${activeCategories[1]} активних категорій` : `${activeCategories[1]} активных категорий`;
  const categoryAllowance = value.match(/^(\d+) (Yellow|Blue) · one category per employee per quarter$/);
  if (categoryAllowance) return language === 'uk'
    ? `${categoryAllowance[1]} ${categoryAllowance[2]} · одна категорія на працівника за квартал`
    : `${categoryAllowance[1]} ${categoryAllowance[2]} · одна категория на сотрудника за квартал`;
  const needMore = value.match(/^You need (\d+) more (White|Yellow|Blue) Sparks for this conversion\.$/);
  if (needMore) return language === 'uk'
    ? `Для цієї конвертації потрібно ще ${needMore[1]} ${needMore[2]} Sparks.`
    : `Для этой конвертации нужно ещё ${needMore[1]} ${needMore[2]} Sparks.`;
  const awardedBy = value.match(/^Awarded by (.+)$/);
  if (awardedBy) return language === 'uk' ? `Нагородив: ${awardedBy[1]}` : `Наградил: ${awardedBy[1]}`;
  const seeMore = value.match(/^See more \((\d+)\)$/);
  if (seeMore) return language === 'uk' ? `Показати ще (${seeMore[1]})` : `Показать ещё (${seeMore[1]})`;
  const showMoreAchievements = value.match(/^Show more achievements \((\d+)\)$/);
  if (showMoreAchievements) return language === 'uk' ? `Показати більше досягнень (${showMoreAchievements[1]})` : `Показать больше достижений (${showMoreAchievements[1]})`;
  const gateUntil = value.match(/^Gate until (.+)$/);
  if (gateUntil) return language === 'uk' ? `Обмеження до ${gateUntil[1]}` : `Ограничение до ${gateUntil[1]}`;
  const monthlyAccounting = value.match(/^Monthly accounting · (.+)$/);
  if (monthlyAccounting) return language === 'uk' ? `Щомісячна бухгалтерія · ${monthlyAccounting[1]}` : `Ежемесячная бухгалтерия · ${monthlyAccounting[1]}`;
  const displayDate = value.match(/^(MONDAY|TUESDAY|WEDNESDAY|THURSDAY|FRIDAY|SATURDAY|SUNDAY) (\d{1,2}) (JANUARY|FEBRUARY|MARCH|APRIL|MAY|JUNE|JULY|AUGUST|SEPTEMBER|OCTOBER|NOVEMBER|DECEMBER)$/i);
  if (displayDate) {
    const weekdays = language === 'uk'
      ? ['ПОНЕДІЛОК', 'ВІВТОРОК', 'СЕРЕДА', 'ЧЕТВЕР', 'П’ЯТНИЦЯ', 'СУБОТА', 'НЕДІЛЯ']
      : ['ПОНЕДЕЛЬНИК', 'ВТОРНИК', 'СРЕДА', 'ЧЕТВЕРГ', 'ПЯТНИЦА', 'СУББОТА', 'ВОСКРЕСЕНЬЕ'];
    const months = language === 'uk'
      ? ['СІЧНЯ', 'ЛЮТОГО', 'БЕРЕЗНЯ', 'КВІТНЯ', 'ТРАВНЯ', 'ЧЕРВНЯ', 'ЛИПНЯ', 'СЕРПНЯ', 'ВЕРЕСНЯ', 'ЖОВТНЯ', 'ЛИСТОПАДА', 'ГРУДНЯ']
      : ['ЯНВАРЯ', 'ФЕВРАЛЯ', 'МАРТА', 'АПРЕЛЯ', 'МАЯ', 'ИЮНЯ', 'ИЮЛЯ', 'АВГУСТА', 'СЕНТЯБРЯ', 'ОКТЯБРЯ', 'НОЯБРЯ', 'ДЕКАБРЯ'];
    const dayIndex = ['MONDAY', 'TUESDAY', 'WEDNESDAY', 'THURSDAY', 'FRIDAY', 'SATURDAY', 'SUNDAY'].indexOf(displayDate[1].toUpperCase());
    const monthIndex = ['JANUARY', 'FEBRUARY', 'MARCH', 'APRIL', 'MAY', 'JUNE', 'JULY', 'AUGUST', 'SEPTEMBER', 'OCTOBER', 'NOVEMBER', 'DECEMBER'].indexOf(displayDate[3].toUpperCase());
    return `${weekdays[dayIndex]} ${displayDate[2]} ${months[monthIndex]}`;
  }
  const shortDate = value.match(/^(\d{1,2}) (Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)(,? .*)?$/);
  if (shortDate) {
    const monthIndex = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'].indexOf(shortDate[2]);
    const months = language === 'uk'
      ? ['січ.', 'лют.', 'бер.', 'квіт.', 'трав.', 'черв.', 'лип.', 'серп.', 'вер.', 'жовт.', 'лист.', 'груд.']
      : ['янв.', 'февр.', 'мар.', 'апр.', 'мая', 'июн.', 'июл.', 'авг.', 'сент.', 'окт.', 'нояб.', 'дек.'];
    return `${shortDate[1]} ${months[monthIndex]}${shortDate[3] ?? ''}`;
  }
  return value;
};

export function localizeContent(language: InterfaceLanguage, value: string) {
  if (language === 'en') return value;
  const trimmed = value.trim();
  if (!trimmed) return value;
  const translated = maps[language][trimmed] ?? dynamic(language, trimmed);
  if (translated === trimmed) return value;
  return value.replace(trimmed, translated);
}
